import{_ as a,c as o,o as s,ah as i,ao as t,ap as r}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"Nem um Pardal É Esquecido — Ele Nunca Passou Despercebido","description":"Jesus disse que nem um pardal cai sem que o Pai saiba. O que Mateus e os Salmos dizem sobre o cuidado de Deus pelos animais.","frontmatter":{"title":"Nem um Pardal É Esquecido — Ele Nunca Passou Despercebido","description":"Jesus disse que nem um pardal cai sem que o Pai saiba. O que Mateus e os Salmos dizem sobre o cuidado de Deus pelos animais."},"headers":[],"relativePath":"pt/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"pt/pets-in-heaven/not-one-sparrow-forgotten.md"}'),n={name:"pt/pets-in-heaven/not-one-sparrow-forgotten.md"};function u(p,e,d,l,c,m){return s(),o("div",null,[...e[0]||(e[0]=[i('<div class="pl-quote"><p>“Ele era só um animal pequeno. O mundo vai lembrar dele? Ou sou só eu?”</p><p class="pl-quote-soft">Jesus respondeu a essa pergunta uma vez, e a resposta Dele é mais gentil do que esperamos.</p></div><section class="pl-section"><h2>1. Jesus disse: nem um pardal cai sem o Pai</h2><blockquote><p><strong>Mateus 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>Nos dias de Jesus, pardais estavam entre as coisas mais baratas que se podia comprar — dois por uma moedinha. Eram o tipo de vida que ninguém notava.</p><p>E Jesus disse: <strong>sem o seu Pai, nem um deles cai no chão.</strong></p><p>A palavra “cair” ali significa morte. Jesus está dizendo que a morte do pássaro mais barato não é um acidente que Deus não percebeu. A partida dele é vista. É registrada.</p><p>Se o seu companheiro era pequeno, o tipo de animal que o mundo chama de “só um animal” — este versículo foi escrito para você. Deus se lembra dos pardais. Ele não vai esquecer o seu.</p></section><section class="pl-section"><h2>2. Ele os alimentou — nenhum dia faltou</h2><blockquote><p><strong>Salmos 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>Davi também escreveu:</p><blockquote><p><strong>Salmos 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>“O homem e o animal” — a palavra no original abrange animais selvagens e domésticos. Deus coloca os animais na Sua lista de quem Ele preserva, não como um detalhe, mas lado a lado conosco.</p><p>O que isso significa? Que do primeiro ao último dia deles, cada refeição, cada inverno, cada hora em que você estava fora, Deus estava cuidando. Você pensou que cuidava sozinho. Você estava cuidando junto com Deus.</p></section><section class="pl-section"><h2>3. Ele pertence a Deus — e isso é o lugar mais seguro</h2><blockquote><p><strong>Salmos 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>Deus diz: “Todo animal da floresta é meu. O gado sobre mil colinas. Eu conheço todas as aves dos montes.”</p><p>Seu pet nunca foi propriedade sua. Ele foi um presente que Deus confiou aos seus cuidados. E quando quem dá o presente o toma de volta, Ele não o joga fora — Ele <strong>o leva para casa, para junto de Si</strong>.</p><p>Você não sabe como Ele cuida dele agora, onde ele está, ou se lembra da sua voz. Mas você sabe em cujas mãos ele está: as mãos que contaram os pardais.</p><p class="pl-quote-soft">Se hoje você só conseguir guardar uma frase, guarde esta:</p></section><div class="pl-quote"><p>“Ele nunca saiu da vista de Deus. Nem agora.”</p></div><section class="pl-section"><h2>Uma oração que você pode tentar</h2><p>“Senhor, obrigado por confiar ele a mim por esses anos.<br>Obrigado por cuidar dele onde eu não podia ver.<br>Não posso mais segurá-lo nos braços, mas sei que Tuas mãos são maiores que as minhas.<br>Por favor, cuide dele, como cuidas de cada pardal.<br>E cuide de mim, porque sinto muita falta. Amém.”</p><p><a href="/pt/pets-in-heaven/">← Voltar para Pets in Heaven</a> ｜ Próximo: <a href="/pt/pets-in-heaven/rainbow-bridge-covenant">Além da Ponte do Arco-Íris</a></p></section><div class="pl-cta"><h2>Ele tem um nome.</h2><p>Escreva o nome dele e um pequeno hábito que só você conhecia. Esses detalhes merecem ser guardados.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Baixar na App Store</a></div><div class="pl-bible"><h3>Deixe a Palavra de Deus continuar com você</h3><p>Todos os versículos deste artigo vêm da Bíblia. Com o Rainbow Bible, você pode ler as Escrituras a qualquer momento e criar um widget de versículo diário — uma pequena luz nos dias em que sente saudade.</p><div class="pl-bible-shots"><figure><img src="'+t+'" alt="Widget do Rainbow Bible exibindo 2 Timóteo 2:13" loading="lazy"><figcaption>Versículo diário na tela inicial</figcaption></figure><figure><img src="'+r+'" alt="App Rainbow Bible — tema Pets no Céu exibindo Mateus 10:29-31" loading="lazy"><figcaption>Leia a Palavra no tema Pets no Céu</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Baixar o Rainbow Bible na App Store</a></div>',8)])])}const g=a(n,[["render",u]]);export{v as __pageData,g as default};
